const MOBILE_REGISTRATION_CALLBACK="todijo://auth/registration";
const AUTH_ERROR_CODES=["INVALID_CREDENTIALS","ACCOUNT_BLOCKED","ACCOUNT_DEACTIVATED","EMAIL_NOT_VERIFIED","RATE_LIMITED","SESSION_EXPIRED","INVALID_REFRESH_TOKEN","REGISTRATION_ATTEMPT_EXPIRED","REGISTRATION_PROOF_INVALID","REGISTRATION_PROOF_EXPIRED"];
const ORDER_PUBLIC_STATUSES=["PENDING","PAID","PROCESSING","SHIPPED","DELIVERED","CANCELLED","REFUNDED"];
const REFUND_PUBLIC_STATUSES=["PENDING","SELLER_APPROVED","SELLER_REJECTED","ADMIN_APPROVED","ADMIN_REJECTED"];
const RETURN_PUBLIC_STATUSES=["PENDING","SELLER_APPROVED","SELLER_REJECTED","ESCALATED","RESOLVED"];
const isTodijoLocale=value=>TODIJO_LOCALES.includes(value);
const isTodijoRtlLocale=value=>TODIJO_RTL_LOCALES.includes(value);
module.exports={TODIJO_LOCALES,TODIJO_RTL_LOCALES,MARKETPLACE_SORTS,MOBILE_REGISTRATION_CALLBACK,AUTH_ERROR_CODES,ORDER_PUBLIC_STATUSES,REFUND_PUBLIC_STATUSES,RETURN_PUBLIC_STATUSES,isTodijoLocale,isTodijoRtlLocale};
